{
  "name": "@smykla-skalski/opencode-plugin-plan-review",
  "version": "0.2.0",
  "description": "opencode v2 plugin for reviewable planning in the terminal: short structured plans reviewed step by step, batched questions, planning inside the build loop with checkpoints, and a what-changed digest",
  "license": "MIT",
  "author": "Marcin Skalski (https://github.com/Automaat)",
  "type": "module",
  "exports": {
    "./server": "./server.ts",
    "./tui": "./tui.tsx",
    "./rpc": "./rpc.ts"
  },
  "files": [
    "server.ts",
    "tui.tsx",
    "rpc.ts",
    "src",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "opencode": ">=2.0.19"
  },
  "keywords": [
    "ai",
    "code-review",
    "coding-agent",
    "opencode",
    "opencode-plugin",
    "plan-mode",
    "planning",
    "tui"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/smykla-skalski/opencode-plugin-plan-review.git"
  },
  "bugs": {
    "url": "https://github.com/smykla-skalski/opencode-plugin-plan-review/issues"
  },
  "homepage": "https://github.com/smykla-skalski/opencode-plugin-plan-review#readme",
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.19",
    "@opentui/core": ">=0.5.12",
    "@opentui/solid": ">=0.5.12",
    "solid-js": ">=1.9.0"
  },
  "dependencies": {
    "beautiful-mermaid": "1.1.3",
    "zod": "4.6.5"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.19",
    "@opentui/core": "0.5.12",
    "@opentui/solid": "0.5.12",
    "@types/node": "24.19.0",
    "solid-js": "1.9.12",
    "typescript": "7.0.2"
  },
  "scripts": {
    "typecheck": "tsc -p .",
    "test": "node --experimental-strip-types --test --test-force-exit test/*.test.ts"
  }
}
